const main=document.querySelector('main');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>esc(JSON.stringify(x,null,2));
const get=async(path,body)=>{const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,data:await r.json()}};
const stamp=s=>`<span class="stamp ${s==='recorded'?'caution':''}">${s==='recorded'?'Recorded — not re-run by fvapi':'Replay available'}</span>`;
const intro=(title,text)=>`<div class="intro"><h1>${title}</h1><p>${text}</p></div>`;
function card(e){return `<article class="card"><div class="callno">${esc(e.id)} / ${esc(e.kind)}</div><h3>${esc(e.title)}</h3><p class="claim">${esc(e.claim)}</p>${stamp(e.replay_status)}<br><a href="#entry/${encodeURIComponent(e.id)}">Pull this card</a></article>`}
async function catalog(){const {data}=await get('catalog');let kind='all';main.innerHTML=intro('The proof catalog',`${data.entries.length} cards on file. Select a drawer, then pull a card.`)+`<section class="cabinet" aria-label="Catalog cabinet"><div class="drawers">${['all',...new Set(data.entries.map(e=>e.kind))].map(k=>`<button class="drawer ${k==='all'?'selected':''}" data-kind="${esc(k)}"><span>${k==='all'?'All entries':esc(k)}</span></button>`).join('')}</div><div class="cards"></div></section>`;const paint=()=>main.querySelector('.cards').innerHTML=data.entries.filter(e=>kind==='all'||e.kind===kind).map(card).join('');paint();main.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;main.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('selected',x===b));paint()})}
async function entry(id){const {status,data:e}=await get('catalog/'+encodeURIComponent(id));if(status!==200){const {data}=await get('catalog');const s=data.entries.find(e=>e.id===id);main.innerHTML=intro('Card summary','The full holdings record is unavailable.')+(s?card(s):'<p>Entry not found. Return to the catalog to choose another card.</p>');return}main.innerHTML=intro('A card from the library','Read the claim and statement before you use this proof.')+`<div class="detail"><article class="card"><div class="callno">Call number: ${esc(e.id)} / ${esc(e.kind)}</div><h1>${esc(e.title)}</h1>${stamp(e.replay.status)}<p>${esc(e.claim)}</p>${e.replay.status==='recorded'?`<div class="notice"><strong>Not re-run by fvapi.</strong><p>This transcript is a recorded prototype stub from an earlier source run. It is not a fresh verification.</p>${esc(e.replay.note)}</div>`:''}<div class="section"><h2>Statements to match</h2>${e.statements.map(s=>`<p>${esc(s.name)}<br><small>${esc(s.file)}:${s.line}</small></p><pre>${esc(s.text)}</pre>`).join('')}</div><div class="section"><h2>Holdings in the bundle</h2><ul class="holdings">${e.closure.map(f=>`<li><strong>${esc(f.path)}</strong> / ${f.bytes} bytes<span class="hash">sha256 ${esc(f.sha256)}</span></li>`).join('')}</ul><a class="button" href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a></div><div class="section"><h2>Replay at your desk</h2><p>${esc(e.toolchain)}<br>Requires: ${esc(e.requires.join(', '))}</p><pre id="command">${esc(e.replay.command)}</pre><button id="copy">Copy replay command</button><h3>Expected axioms</h3><p>${esc(e.replay.expect_axioms.join(', ')||'None')}</p>${e.replay.transcript?`<pre>${typeof e.replay.transcript==='string'?esc(e.replay.transcript):json(e.replay.transcript)}</pre>`:''}</div><div class="section"><h2>Source and licence</h2><p>${esc(e.source.repo)}<br>Commit: <code>${esc(e.source.commit)}</code></p><pre>${esc(e.source.paths.join('\n'))}</pre><p>${esc(e.licence.spdx)}</p><h3>Third-party notices</h3>${e.licence.third_party.length?e.licence.third_party.map(n=>`<p>${esc(n.name)} / ${esc(n.spdx)}<br>${esc(n.source)}</p>`).join(''):'<p>No third-party notices listed.</p>'}</div><div class="actions"><a href="#check/${encodeURIComponent(e.id)}" class="button">Run check on this entry</a><a href="#catalog" class="button">Return to drawers</a></div></article></div>`;document.querySelector('#copy').onclick=async ev=>{try{await navigator.clipboard.writeText(e.replay.command);ev.target.textContent='Command copied'}catch{ev.target.textContent='Select the command above to copy it'}}}
async function lookup(mode){main.innerHTML=intro('Fill out a call slip','An exact match pulls a proof card. A miss goes to the acquisitions tray.')+`<div class="desk"><form class="slip" id="lookup"><h2>Request from the library</h2><label for="key">Find by</label><select id="key"><option value="spec_id">Entry ID</option><option value="artifact_sha256">Artifact SHA-256</option><option value="statement">Statement text</option></select><label for="query">Your request</label><textarea id="query" required placeholder="Enter an ID, digest, or statement">${mode==='miss'?'unfiled.example':'vf.contrast-2x2'}</textarea><div class="actions"><button class="primary">Look up</button></div><p class="muted">No LLM handles this request. Only library matches are returned.</p></form><section id="result" aria-live="polite" class="result"><p class="empty">Fill in the slip to request a card.</p></section></div>`;const submit=async ev=>{ev?.preventDefault();const {status,data}=await get('lookup',{[document.querySelector('#key').value]:document.querySelector('#query').value});document.querySelector('#result').innerHTML=status===200?`<article class="slip"><span class="stamp">Card located</span><h2>Match found</h2><p>Answer slip ${esc(data.answer_id)}<br>Matched on ${esc(data.matched_on)}</p>${card({...data.entry,replay_status:data.entry.replay.status})}</article>`:status===404?`<article class="slip"><span class="stamp caution">Acquisition request</span><h2>No matching card</h2><div class="notice">${data.logged?'Logged as demand.':'Demand logging was not confirmed.'}</div><p>${esc(data.detail)}</p><p>Request: ${esc(data.miss_id)}</p><a href="#demand">Open the acquisitions tray</a></article>`:`<div class="notice">${esc(data.detail||data.error)} Check your request and try again.</div>`};document.querySelector('#lookup').onsubmit=ev=>submit(ev).catch(err=>{document.querySelector('#result').innerHTML=`<div class="notice">The lookup could not finish. ${esc(err.message)}. Check the API connection, then try again.</div>`});if(mode)await submit()}
async function check(mode,id='vf.contrast-2x2'){const {data:catalog}=await get('catalog');const {data:e}=await get('catalog/vf.contrast-2x2');let input=structuredClone(e.check.example_input);if(mode==='reject')input.rows[0].weights[0]=1;if(mode==='409')id=catalog.entries.find(e=>e.kind!=='checker').id;main.innerHTML=intro('Test a submitted input','The server checks your input. Re-run the check locally before you rely on it.')+`<div class="desk"><form id="check" class="slip"><h2>Checker call slip</h2><label for="entryid">Entry</label><select id="entryid">${catalog.entries.map(c=>`<option value="${esc(c.id)}" ${c.id===id?'selected':''}>${esc(c.id)} (${esc(c.kind)})</option>`).join('')}</select><label for="input">Input JSON (editable)</label><textarea id="input" spellcheck="false">${json(input)}</textarea><div class="actions"><button class="primary">Run check</button><button type="button" id="example">Restore example</button></div></form><section id="result" class="result" aria-live="polite"><p class="empty">Submit an input to receive a check slip.</p></section></div>`;const submit=async ev=>{ev?.preventDefault();const target=document.querySelector('#result');try{const body=JSON.parse(document.querySelector('#input').value);const {status,data}=await get('checks/'+encodeURIComponent(document.querySelector('#entryid').value),body);target.innerHTML=status===200?`<article class="slip"><span class="stamp ${data.verdict==='accept'?'':'caution'}">${esc(data.verdict)}</span><h2>Check ${esc(data.verdict==='accept'?'accepted':'rejected')}</h2><p>Answer slip ${esc(data.answer_id)}</p><p>${esc(data.ran_on)} / ${data.elapsed_ms} ms / exit ${data.exit_code}</p><pre>${json(data.output)}</pre><h3>Recheck independently</h3><pre>${esc(data.recheck.command)}</pre><p class="hash">Input SHA-256: ${esc(data.input_sha256)}</p></article>`:`<article class="slip"><span class="stamp caution">HTTP ${status}</span><h2>${status===409?'This card has no checker':'Check could not run'}</h2><p>${esc(data.detail||data.error)}</p><p>Select a checker entry, then run the check again.</p></article>`}catch(err){target.innerHTML=`<div class="notice">${esc(err.message)}. Enter valid JSON, then try again.</div>`}};document.querySelector('#check').onsubmit=submit;document.querySelector('#example').onclick=()=>document.querySelector('#input').value=JSON.stringify(e.check.example_input,null,2);if(mode)await submit()}
async function logs(type){const {data}=await get(type);if(type==='demand'){main.innerHTML=intro('The acquisitions tray','Unmatched requests are logged as demand, not assigned to an agent.')+`<div class="desk"><section class="slip"><h2>Requests on file</h2>${data.misses.length?data.misses.map(m=>`<div class="section"><span class="stamp caution">Awaiting acquisition</span><p>${esc(m.miss_id)}<br>${esc(m.at)}</p><pre>${json(m.query)}</pre></div>`).join(''):'<p>No misses yet. Use a call slip to look for an entry.</p>'}</section><section class="slip"><h2>Repeated requests</h2>${data.by_key.map(k=>`<div class="section"><span class="count">${k.count}</span><p class="hash">${esc(k.key)}</p></div>`).join('')||'<p>No request counts yet.</p>'}</section></div>`}else{main.innerHTML=intro('Answer slips','A record of what the library returned. An answer is not a substitute for replay.')+`<div class="log">${data.answers.map(a=>`<article class="slip"><span class="stamp">${esc(a.verdict||a.kind)}</span><h2>${esc(a.answer_id)}</h2><p>${esc(a.at)}<br>${esc(a.kind)} / ${esc(a.entry_id)}</p><a href="#entry/${encodeURIComponent(a.entry_id)}">Pull the entry card</a></article>`).join('')||'<p>No answer slips yet. Run a lookup or check.</p>'}</div>`}}
async function route(){const [view='catalog',arg]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.dataset.ready='false';try{if(view==='entry')await entry(decodeURIComponent(arg||'vf.contrast-2x2'));else if(view==='recorded')await entry('fva.glm-iround');else if(view==='lookup'||view.startsWith('lookup-'))await lookup(view.split('-')[1]);else if(view==='check'||view.startsWith('check-'))await check(view.split('-')[1],arg?decodeURIComponent(arg):undefined);else if(['demand','answers'].includes(view))await logs(view);else await catalog();main.dataset.ready='true'}catch(e){main.innerHTML=`<div class="notice"><h1>The library could not respond</h1><p>${esc(e.message)}. Check the API connection, then reload this page.</p></div>`;main.dataset.ready='error'}}
window.addEventListener('hashchange',route);route();
